import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheet';
import { GRADES, peopleKey, useCloseEditor, useEditingPerson, usePeople, useShowRetired } from './people';
import type { Person } from './people';
import { claimsKey } from '../claims/claims';
import { useSheetToday } from '../sheet/sheet';

/** One form that adds a person, or edits the one whose editor is open (filled with their values). An added
 *  person's grade applies from the beginning of time; an edit records the grade from its from-date (the sheet's
 *  today unless changed), keeping the grades already recorded from other dates. The person's own terms (days; blank
 *  for none) are set by an add when given, and by an edit whose terms field was entered (blank clears them); so is
 *  their contact, stored trimmed and lower-cased. A contact another person on the sheet already has is refused at once
 *  (an add's contact field is then cleared), keeping the editor open (the
 *  version it remembers brought up to date, so saving again is from the person as now stored). The
 *  editor remembers the version it loaded: when someone else has saved the person since, the save is
 *  refused and the form is refilled with the person as now stored (so saving again is from that). Any other refused
 *  edit closes the editor, leaving the person as stored and the refusal showing on the form (now adding). */
function PersonForm({ sheetId, user, editing, carried, onRefused }: { sheetId: string; user: string; editing?: Person;
  carried: string; onRefused: (error: string) => void }) {
  const queryClient = useQueryClient();
  const [, setEditing] = useEditingPerson();
  const [name, setName] = useState(editing?.name ?? '');
  const [grade, setGrade] = useState(editing?.grade ?? 'A');
  const [terms, setTerms] = useState(editing?.terms != null ? String(editing.terms) : '');
  const [contact, setContact] = useState(editing?.contact ?? '');
  const [termsGiven, setTermsGiven] = useState(false);
  const [contactGiven, setContactGiven] = useState(false);
  const people = usePeople(sheetId);
  const closeEditor = useCloseEditor();
  const [version, setVersion] = useState(editing?.version);
  const today = useSheetToday(sheetId);
  const [gradeFromEntered, setGradeFrom] = useState<string>();
  const gradeFrom = gradeFromEntered ?? today;
  const [own, showError] = useState('');
  /** The refusal of an editor just closed shows on the form (now adding) until the form is changed, submitted or
   *  an editor opened. Read as it is now, not copied as the form opens: the editor closes (a URL change) and the
   *  refusal is carried in separate updates, either of which may render first. */
  const error = own || (editing ? '' : carried);
  /** Show (or with '' remove) the form's error; removing it also drops a carried refusal. */
  const setError = (message: string) => {
    showError(message);
    if (message === '' && carried) onRefused('');
  };
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (body: { user: string; name: string; grade: string; version?: number; gradeFrom?: string;
      terms?: string; contact?: string }) =>
      editing
        ? putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${editing.id}`, body)
        : postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setName('');
      setGrade('A');
      setTerms('');
      setContact('');
      // Only this person's editor: another may have been opened while the save was on its way.
      if (editing) closeEditor(editing.id);
    },
    onError: async (e) => {
      if (editing && e instanceof HttpError && e.status === 412) {
        const people = await getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`);
        queryClient.setQueryData(peopleKey(sheetId), people);
        const current = people.find((p) => p.id === editing.id);
        if (current) {
          setName(current.name);
          setGrade(current.grade);
          setTerms(current.terms != null ? String(current.terms) : '');
          setContact(current.contact ?? '');
          setVersion(current.version);
        }
      }
      refuse(
        e instanceof HttpError && (e.status === 409 || e.status === 412) && e.body
          ? e.body
          : 'Could not save this person: a name is required, the grade must be A, B or C, the from-date a date and the terms blank or a whole number of days.',
        e instanceof HttpError && e.status === 412,
      );
    },
    onSettled: once.done,
  });

  /** Show the refusal; a refused edit (other than a stale one, refilled to save again) closes the editor. */
  const refuse = (message: string, stale = false) => {
    if (editing && !stale) {
      onRefused(message);
      setEditing(undefined);
    } else {
      setError(message);
    }
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (name.trim() === '') {
      refuse('A name is required.');
      return;
    }
    if (!/^\d{0,4}$/.test(terms.trim())) {
      refuse('The terms must be a whole number of days, 0 or more, or blank for none.');
      return;
    }
    const key = contact.trim().toLowerCase();
    if (key !== '' && (!editing || contactGiven) && (people.data ?? []).some((p) => p.id !== editing?.id && p.contact === key)) {
      setError(`The contact ${key} is already in use on this sheet.`);
      // An add refused for its contact starts the next add with no contact.
      if (!editing) setContact('');
      if (editing) {
        void getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`).then((latest) => {
          queryClient.setQueryData(peopleKey(sheetId), latest);
          const current = latest.find((p) => p.id === editing.id);
          if (current) setVersion(current.version);
        });
      }
      return;
    }
    if (!once.start()) return;
    save.mutate(
      editing
        ? { user, name, grade, version, gradeFrom: gradeFrom.trim() === '' ? undefined : gradeFrom, terms: termsGiven ? terms.trim() : undefined,
            contact: contactGiven ? key : undefined }
        : { user, name, grade, terms: terms.trim() === '' ? undefined : terms.trim(), contact: key === '' ? undefined : key },
    );
  };

  return (
    <form data-testid="person-form" onSubmit={submit}>
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            setError('');
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Terms (days){' '}
        <input
          data-testid="person-form-terms"
          value={terms}
          onKeyDown={() => setTermsGiven(true)}
          onChange={(e) => {
            setTerms(e.target.value);
            setTermsGiven(true);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Contact{' '}
        <input
          data-testid="person-form-contact"
          value={contact}
          onKeyDown={() => setContactGiven(true)}
          onChange={(e) => {
            setContact(e.target.value);
            setContactGiven(true);
            setError('');
          }}
        />
      </label>{' '}
      {editing && (
        <>
          <label>
            Grade from{' '}
            <input
              type="date"
              data-testid="person-form-grade-from"
              value={gradeFrom}
              onChange={(e) => {
                setGradeFrom(e.target.value);
                setError('');
              }}
            />
          </label>{' '}
        </>
      )}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add person'}
      </button>
      {editing && (
        <button type="button" data-testid="person-form-cancel" onClick={() => {
          onRefused('');
          setEditing(undefined);
        }}>
          Cancel
        </button>
      )}
      {error && (
        <p data-testid="person-form-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

/** The quick-add bar: a name and an amount make a DRAFT claim dated the sheet's entry date (while it is set, else its today) with an empty note for
 *  the person of that name, adding them first with grade A when the name is new to the sheet. A refusal adds
 *  nothing and shows why on the bar. */
function QuickAddBar({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const add = useMutation({
    mutationFn: (body: { user: string; name: string; amount: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, body),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
      setName('');
      setAmount('');
    },
    onError: (e) =>
      setError(
        e instanceof HttpError && e.body
          ? e.body
          : 'Could not quick-add: a name is required and the amount must be a number, 0.00 or more, with up to two decimals.',
      ),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (name.trim() === '') {
      setError('A name is required.');
      return;
    }
    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount.trim())) {
      setError('The amount must be a number, 0.00 or more, with up to two decimals.');
      return;
    }
    if (!once.start()) return;
    add.mutate({ user, name, amount });
  };

  return (
    <form data-testid="quick-add" onSubmit={submit}>
      <label>
        Name{' '}
        <input
          data-testid="quick-name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <label>
        Amount{' '}
        <input
          data-testid="quick-amount"
          value={amount}
          onChange={(e) => {
            setAmount(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Quick add
      </button>
      {error && (
        <p data-testid="quick-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

/** The sheet's people in the order they were added, each with their name and grade. Retired people have no
 *  row unless "show retired" is on. */
function People({ sheetId, user }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId);
  const [editingId, setEditing] = useEditingPerson();
  const editing = people.data?.find((p) => String(p.id) === editingId);
  const [showRetired, setShowRetired] = useShowRetired();
  const [carried, setCarried] = useState('');
  const listed = (people.data ?? []).filter((p) => showRetired || p.retiredFrom === null);

  return (
    <section data-testid="people">
      <h2>People</h2>
      {/* Keyed by who is being edited, so opening an editor fills the form with their values. */}
      <PersonForm key={editing ? editing.id : 'new'} sheetId={sheetId} user={user} editing={editing}
        carried={carried} onRefused={setCarried} />
      <QuickAddBar sheetId={sheetId} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      <table>
        <tbody>
          {listed.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-terms">{p.terms ?? ''}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => {
                  setCarried('');
                  setEditing(String(p.id));
                }}>
                  Edit
                </button>
              </td>
              <PersonRow.Slot sheetId={sheetId} user={user} person={p} />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 10, Component: People });
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

/** A person on a sheet: a name and a grade (A, B or C: the one in force on the sheet's today), the version stored (one more on each edit), how many
 *  statements have been taken of them, and the last one's due-total (null when n/a, or none taken) and date
 *  (the sheet's today then; null when none taken), the date they are retired from (null: not retired), whether
 *  they have any hold, their dated grades, earliest first, and their holds in the order they were put on (their OPEN
 *  claims dated within one, not bound by a statement, count in no live total), their own terms in days (null: none), and their contact (trimmed, lower-cased; null: none). */
export type Person = { id: number; name: string; grade: string; version: number; statementCount: number;
  statedTotal: string | null; statementDate: string | null; retiredFrom: string | null; held: boolean;
  grades: Grade[]; holds: Hold[]; terms: number | null;
  contact: string | null };

/** A hold on a person, from its from-date to its to-date, both included (yyyy-mm-dd, or null: unbounded on that side). */
export type Hold = { from: string | null; to: string | null };

/** Whether one of the person's holds covers the date (yyyy-mm-dd). */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

/** Whether the person's retirement date is reached on the sheet's today (yyyy-mm-dd; '' while loading: not reached):
 *  from then their OPEN and PENDING claims not bound by a statement count in no live total. */
export function retiredOn(person: Person | undefined, today: string): boolean {
  return today !== '' && person?.retiredFrom != null && person.retiredFrom <= today;
}

/** A grade a person was given, in force from its from-date (yyyy-mm-dd, or null: from the beginning of time). */
export type Grade = { grade: string; from: string | null };

/** The person's grade in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or before it,
 *  a grade with no from-date applying from the beginning of time; '' when none applies. */
export function gradeOn(person: Person | undefined, date: string): string {
  let found: Grade | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') <= (g.from ?? '')) found = g;
  }
  return found?.grade ?? '';
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
  });
}

/** The id of the person whose editor is open ('' when the form adds a new person). */
export function useEditingPerson() {
  return useSearchParam('editPerson', asString);
}

/** Close the person's editor, when it is still theirs that is open (another may have been opened since). */
export function useCloseEditor() {
  const navigate = useNavigate();
  return (personId: number) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        if (prev.editPerson !== String(personId)) return prev;
        const next = { ...prev };
        delete next.editPerson;
        return next;
      },
      replace: true,
    });
}

/** Whether retired people are listed: off when the screen is first opened, and left as it is by loading a sheet. */
export function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}
import { useEffect, useState } from 'react';

// Every action on a person's row shows its refusal in the row's one person-error; taking any action on the
// row clears the error an earlier one left, so a row never shows a stale refusal next to a new one.
const clearers = new Map<string, Set<() => void>>();

/** This cell's error on the person's row, its setter, and `begin`: call it as an action on the row is taken
 *  to clear every error the row's cells show. */
export function usePersonError(sheetId: string, personId: number | string) {
  const key = `${sheetId}/${personId}`;
  const [error, setError] = useState('');
  useEffect(() => {
    const clear = () => setError('');
    const set = clearers.get(key) ?? new Set();
    set.add(clear);
    clearers.set(key, set);
    return () => {
      set.delete(clear);
      if (set.size === 0) clearers.delete(key);
    };
  }, [key]);
  const begin = () => clearers.get(key)?.forEach((clear) => clear());
  return { error, setError, begin };
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { useSheetToday } from '../sheet/sheet';
import { peopleKey } from './people';
import { usePersonError } from './rowError';
import type { Person } from './people';

/** Whether the person has any hold, their holds, and the form that adds one from a from-date (blank: the sheet's
 *  today) to an optional to-date (blank: open-ended). Only their OPEN claims dated within a hold, and not bound by
 *  a statement, count in no live total; a hold ends on its to-date. */
function PersonHold({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheetId);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const hold = useMutation({
    mutationFn: (body: { user: string; from: string; to: string }) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/hold`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setFrom('');
      setTo('');
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not hold ${person.name}: the dates must be yyyy-mm-dd.`),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    begin();
    if (!once.start()) return;
    hold.mutate({ user, from: from.trim(), to: to.trim() });
  };

  const change = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <td>
      Hold <span data-testid="person-hold">{person.holds.length > 0 ? 'yes' : 'no'}</span>
      <ul>
        {person.holds.map((h, i) => (
          <li key={i} data-testid="person-hold-line">
            {h.from ?? 'start'} to {h.to ?? 'open'}
          </li>
        ))}
      </ul>
      <form onSubmit={submit} style={{ display: 'inline' }}>
        <input data-testid="person-hold-from" placeholder={today || 'yyyy-mm-dd'} value={from} onChange={change(setFrom)} />{' '}
        <input data-testid="person-hold-to" placeholder="to (optional)" value={to} onChange={change(setTo)} />{' '}
        <button type="submit" data-testid="person-hold-toggle" disabled={hold.isPending}>
          Hold
        </button>
      </form>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 45, Component: PersonHold });
